    `,isPhishing:!0,difficulty:"intermediate",attackType:"credential-harvest",redFlags:[{category:"identity",description:'Domain "adobe-renewal-center.com"is not adobe.com',severity:"high"},{category:"timing",description:"3-day deadline creates pressure to act without verification",severity:"medium"},{category:"habit",description:"Software renewals go through procurement, not direct email responses",severity:"high"},{category:"knowledge",description:"Clicking will likely lead to payment fraud or credential theft",severity:"high"},{category:"necessity",description:"Verify actual license status through your Adobe admin console",severity:"medium"}],explanation:"Software renewal scams target IT staff and administrators. Attackers know organizations fear service disruption and will act quickly on license warnings. Always verify software license status through official admin consoles and process renewals through your established procurement workflow.",receivedTime:"5 hours ago",links:[{text:"Renew Now - Save 20%",actualUrl:"https://adobe-renewal-center.com/renew/district",displayUrl:"adobe-renewal-center.com"}]},{id:"16",subject:"Staff Meeting Agenda - Thursday 3pm",senderName:"Principal Martinez",senderEmail:"pmartinez@districtschoolboard.org",bodyHtml:`
